 struct TempFileCleanup {
     path: PathBuf,
     keep: std::cell::Cell<bool>,
 }

 impl TempFileCleanup {
     fn new(path: PathBuf) -> Self {
         Self {
             path,
             keep: std::cell::Cell::new(false),
         }
     }

     fn persist(&self) {
         self.keep.set(true);
     }
 }

 impl Drop for TempFileCleanup {
     fn drop(&mut self) {
         if !self.keep.get() {
             let _ = fs::remove_file(&self.path);
         }
     }
 }

