+pub(crate) async fn execute(args: UpgradeArgs) -> Result<CliExitCode, crate::CliError> {
+    let client = ReqwestReleaseClient::new().map_err(|error| message(error.to_string()))?;
+    run_upgrade(&args, &client).await
+}
