+    let file_name = target
+        .file_name()
+        .ok_or_else(|| message(format!("cannot determine file name for {}", target.display())))?
+        .to_string_lossy();
+    let tmp = parent.join(format!(".{file_name}.upgrade-{}.tmp", std::process::id()));
+    let cleanup = TempFileCleanup::new(tmp.clone());
